import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Website update mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"release/website-update.md","filePath":"release/website-update.md"}'),r={name:"release/website-update.md"};function i(d,e,c,n,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="website-update-mechanics" tabindex="-1">Website update mechanics <a class="header-anchor" href="#website-update-mechanics" aria-label="Permalink to &quot;Website update mechanics&quot;">​</a></h1><p>The public site is the <strong>gh-pages branch</strong> of this repository (<a href="https://ocos.cubestudio.cn/" target="_blank" rel="noreferrer">https://ocos.cubestudio.cn/</a>, GitHub Pages). The facade is static: <code>assets/site-data.js</code> carries the version data, <code>download.html</code> / <code>index.html</code> render it, <code>downloads/</code> holds the asset copies.</p><h2 id="the-release-time-update-per-release" tabindex="-1">The release-time update (per release) <a class="header-anchor" href="#the-release-time-update-per-release" aria-label="Permalink to &quot;The release-time update (per release)&quot;">​</a></h2><ol><li>Read the assets from <code>dist/</code>, compute SHA256 + size.</li><li><strong>Facade</strong>: <code>assets/site-data.js</code> - update the <code>dev</code> channel block (version / build / date / the asset four-tuples: name, url, sha, size) and insert the release into the <code>history</code> array head.</li><li><strong>Pages</strong>: <code>download.html</code> + <code>index.html</code> - replace the previous version strings in place (the gh-pages HTML and the archived release HTML have structural differences - do not overwrite the whole file, only the strings).</li><li><strong>OTA manifest</strong>: <code>update.json</code> at the branch root (version, build, time, changes text, package URL/sha/size) - what <code>checkupdate</code> inside the system parses.</li><li><strong>downloads/</strong>: copy the four release assets in (the lowercase <code>opencube-&lt;ver&gt;.*</code> canonical names).</li><li>Two commits (facade + downloads) and push the branch.</li></ol><h2 id="verification-after-it-runs" tabindex="-1">Verification after it runs <a class="header-anchor" href="#verification-after-it-runs" aria-label="Permalink to &quot;Verification after it runs&quot;">​</a></h2><ul><li><code>https://ocos.cubestudio.cn/update.json</code> shows the new version/build/sha.</li><li>The download page&#39;s four hashes equal the Release&#39;s four.</li><li><code>curl -sL &lt;asset-url&gt; | sha256sum</code> on each asset equals its declared SHA256.</li><li>The OTA E2E (<code>tools/run_fix4_regression.py</code> update section + the checkupdate flow) sees &quot;New version available.&quot; on a machine built with a lower build id.</li></ul><h2 id="where-the-numbers-come-from" tabindex="-1">Where the numbers come from <a class="header-anchor" href="#where-the-numbers-come-from" aria-label="Permalink to &quot;Where the numbers come from&quot;">​</a></h2><p><code>tools/update_website.sh &lt;version&gt; &lt;build&gt; [date-iso] [changes]</code> computes the SHA256/size set from <code>dist/</code> and writes the data files (no hand-editing of versions anywhere) - the same numbers the GitHub Release body and the private-mirror audit record carry, so website / Release / mirror hold byte-identical copies.</p>',8)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
